.dbconfig defensive off
BEGIN;
PRAGMA writable_schema = on;
PRAGMA foreign_keys = off;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE playlists (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        snapshot_id TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , image_url TEXT, creator TEXT, created_at TEXT, sync_enabled INTEGER DEFAULT 1, spotify_created_at TEXT, spotify_owner_id TEXT, spotify_is_public INTEGER);
CREATE TABLE tracks (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        artist TEXT NOT NULL,
        album TEXT,
        duration_ms INTEGER
    , release_date TEXT, isrc TEXT, cover_url TEXT, unavailable INTEGER DEFAULT 0, unavailable_archived INTEGER DEFAULT 0, unavailable_reason TEXT, unavailable_at TEXT, manual_url TEXT, manual_located_at TEXT, manual_last_error TEXT);
CREATE TABLE playlist_tracks (
        playlist_id TEXT NOT NULL,
        track_id TEXT NOT NULL,
        added_at TEXT,
        PRIMARY KEY (playlist_id, track_id),
        FOREIGN KEY (playlist_id) REFERENCES playlists(id) ON DELETE CASCADE,
        FOREIGN KEY (track_id)   REFERENCES tracks(id)    ON DELETE CASCADE
    );
CREATE TABLE files (
        track_id TEXT PRIMARY KEY,
        file_path TEXT NOT NULL,
        downloaded_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE
    );
CREATE TABLE sources (
        track_id TEXT PRIMARY KEY,
        url TEXT NOT NULL,
        title TEXT,
        uploader TEXT,
        duration_sec INTEGER,
        checked_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE
    );
CREATE TABLE app_state (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
